extern alias BuilderApp;
using CipherCapsule.Core;
using CipherCapsule.UI;
using System.Security.Cryptography;
using System.Text.Json;
using System.Reflection;
using EditorType=BuilderApp::CipherCapsule.Builder.HtmlEditor;
using BuilderType=BuilderApp::CipherCapsule.Builder.BuilderForm;
using BuilderPassword=BuilderApp::CipherCapsule.UI.PasswordPanel;
internal static partial class Program
{
    static void ExtraTests()
    {
        Test("CF_HTML UTF8 Japanese roundtrip",()=>{string value="<p>日本語 🔑 <a href='https://example.com/'>リンク</a></p>";Check(ClipboardHtml.Decode(ClipboardHtml.Encode(value))==value);});
        Test("CF_HTML invalid offsets rejected",()=>Reject(()=>ClipboardHtml.Decode("StartFragment:999999\r\nEndFragment:9999999\r\nbody")));
        Test("editor warns and sanitizes dangerous source",()=>{string s=SafeHtml.ValidateEditor("<p>保持</p><script>evil()</script>",out bool warning);Check(warning&&s.Contains("保持")&&!s.Contains("evil"));});
        Test("TEXT normal copy OFF blocks native WM_COPY; ON permits",()=>{
            var original=Clipboard.GetDataObject();try{using var host=new AppForm();using var text=new CipherCapsule.Viewer.CopyTextBox{AllowCopy=false,ReadOnly=true,Multiline=true,Dock=DockStyle.Fill,Text="ダミーコピー検証"};host.Controls.Add(text);host.Show();text.Focus();Application.DoEvents();Clipboard.SetText("COPY-MARKER");text.SelectAll();text.Copy();if(Clipboard.GetText()!="COPY-MARKER")throw new Exception("OFF changed clipboard");text.AllowCopy=true;text.SelectAll();text.Copy();if(Clipboard.GetText()!="ダミーコピー検証")throw new Exception("ON failed to copy selection length="+text.SelectionLength+" clipboard length="+Clipboard.GetText().Length);host.Close();}finally{if(original!=null)Clipboard.SetDataObject(original,true);else Clipboard.Clear();}
        });
    }
    static void NewCoreTests(string capsule,string source,bool retainLegacy=false)
    {
        Test("one-character password actual roundtrip",()=>{var d=Path.Combine(Work,"one.exe");using var t=File.OpenRead(Template);Container.Generate(t,d,"一文字パスワード",BodyKind.TEXT,[],Limits.Utf8.GetBytes("🔑"),true,default);using var c=Container.Unlock(d,Limits.Utf8.GetBytes("🔑"),default);Check(c.Manifest.Body=="一文字パスワード");});
        Test("256 scalar password actual roundtrip",()=>{var d=Path.Combine(Work,"256.exe");var p=Limits.Utf8.GetBytes(string.Concat(Enumerable.Repeat("🔐",256)));using var t=File.OpenRead(Template);Container.Generate(t,d,"最大パスワード",BodyKind.TEXT,[],p,true,default);using var c=Container.Unlock(d,p,default);Check(c.Manifest.Body=="最大パスワード");Sodium.Wipe(p);});
        if(!retainLegacy)Test("legacy v1.0.0 decrypt compatibility default copy ON",()=>{var old=Path.GetFullPath(Path.Combine(Root,"../../v1.0.0/work/selftests/TEXT検証.exe"));using var c=Unlock(old);Check(c.Manifest.Body.Contains("日本語の秘密本文")&&c.Manifest.AllowCopy);});
        else Console.WriteLine("RETAINED verified v1.1.1 legacy compatibility result; original fixture was removed by user, Core is unchanged (not counted as executed)");
        Test("copy metadata authenticated and OFF roundtrip",()=>{var d=Path.Combine(Work,"no-copy.exe");using var t=File.OpenRead(Template);Container.Generate(t,d,"コピー禁止",BodyKind.TEXT,[source],Pw,true,default,null,false);using var c=Unlock(d);Check(!c.Manifest.AllowCopy);var saved=Path.Combine(Work,"no-copy-save.txt");c.Save(0,saved,true,default);Check(Hash(saved)==Hash(source));});
        Test("SHA512 ON exact UTF8 lowercase checksum",()=>{var d=Path.Combine(Work,"checksum.exe");using var t=File.OpenRead(Template);var r=PackageWriter.Generate(t,d,"SHA512試験",BodyKind.TEXT,[source],Pw,true,true,default);using var f=File.OpenRead(d);string hash=Convert.ToHexString(SHA512.HashData(f)).ToLowerInvariant();byte[] bytes=File.ReadAllBytes(d+".sha512");Check(!bytes.Take(3).SequenceEqual(new byte[]{239,187,191}));Check(Limits.Utf8.GetString(bytes)==hash+"  checksum.exe\n"&&r.Sha512==hash);});
        Test("SHA512 OFF no sidecar",()=>{var d=Path.Combine(Work,"no-checksum.exe");using var t=File.OpenRead(Template);var r=PackageWriter.Generate(t,d,"off",BodyKind.TEXT,[],Pw,false,true,default);Check(!File.Exists(d+".sha512")&&r.Sha512==null);});
        Test("SHA512 failure preserves existing EXE and sidecar",()=>{var d=Path.Combine(Work,"pair-protect.exe");File.WriteAllText(d,"EXEKEEP");Directory.CreateDirectory(d+".sha512");using var t=File.OpenRead(Template);Reject(()=>PackageWriter.Generate(t,d,"fail",BodyKind.TEXT,[],Pw,true,true,default));Check(File.ReadAllText(d)=="EXEKEEP");Directory.Delete(d+".sha512");});
        Test("pair second commit failure rolls back checksum",()=>{var d=Path.Combine(Work,"pair-rollback.exe");File.WriteAllText(d,"EXEKEEP");File.WriteAllText(d+".sha512","SUMKEEP");using(var locked=new FileStream(d,FileMode.Open,FileAccess.Read,FileShare.Read))using(var t=File.OpenRead(Template))Reject(()=>PackageWriter.Generate(t,d,"rollback",BodyKind.TEXT,[],Pw,true,true,default));Check(File.ReadAllText(d)=="EXEKEEP"&&File.ReadAllText(d+".sha512")=="SUMKEEP");});
        Test("checksum path cannot overwrite attachment original",()=>{var d=Path.Combine(Work,"checksum-input.exe");File.WriteAllText(d+".sha512","ORIGINAL");using var t=File.OpenRead(Template);Reject(()=>PackageWriter.Generate(t,d,"test",BodyKind.TEXT,[d+".sha512"],Pw,true,true,default));Check(File.ReadAllText(d+".sha512")=="ORIGINAL");});
        Test("human size units B to TiB",()=>{Check(Display.Size(10)=="10 B");Check(Display.Size(1024).Contains("KiB"));Check(Display.Size(26261295).StartsWith("25.0 MiB"));Check(Display.Size(1L<<30).Contains("GiB"));Check(Display.Size(1L<<40).Contains("TiB"));});
        Test("output path folder and exe only",()=>{Check(Display.OutputCandidate(Work)==Path.Combine(Work,"SecureMessage.exe"));Check(Display.OutputCandidate(Path.Combine(Work,"future.exe")).EndsWith("future.exe"));Reject(()=>Display.OutputCandidate(source));});
        Test("HTTP safe links retained and escaped",()=>{var s=SafeHtml.Fragment("<a href='https://example.com/?x=1&amp;y=2'>日本語</a>");Check(s.Contains("href=\"https://example.com/?x=1&amp;y=2\"")&&s.Contains("日本語"));});
        foreach(string url in new[]{"javascript:alert(1)","file:///c:/a","data:text/html,evil","vbscript:evil","https://user:password@example.com/"})Test("dangerous link scheme refused "+url.Split(':')[0],()=>Check(SafeHtml.SafeUrl(url)==null));
        Test("JPEG huge dimensions rejected before decode",()=>{byte[] jpeg=[255,216,255,192,0,17,8,255,255,255,255,3,1,17,0,2,17,0,3,17,0,255,217];Check(!SafeHtml.ImageHeader(jpeg,false,out _,out _));Check(SafeHtml.ImageData("data:image/jpeg;base64,"+Convert.ToBase64String(jpeg))==null);});
        Test("valid JPEG header, decode and reencode",()=>{using var b=new Bitmap(4,3);using var ms=new MemoryStream();b.Save(ms,System.Drawing.Imaging.ImageFormat.Jpeg);Check(SafeHtml.ImageHeader(ms.ToArray(),false,out int w,out int h)&&w==4&&h==3);Check(SafeHtml.ImageData("data:image/jpeg;base64,"+Convert.ToBase64String(ms.ToArray()))!=null);});
        Test("PNG huge pixel budget rejected before decode",()=>{using var b=new Bitmap(2,2);using var ms=new MemoryStream();b.Save(ms,System.Drawing.Imaging.ImageFormat.Png);byte[] bytes=ms.ToArray();System.Buffers.Binary.BinaryPrimitives.WriteInt32BigEndian(bytes.AsSpan(16),4096);System.Buffers.Binary.BinaryPrimitives.WriteInt32BigEndian(bytes.AsSpan(20),4096);Check(!SafeHtml.ImageHeader(bytes,true,out _,out _));});
        Test("HTML copy OFF style cannot be overridden",()=>{string html=SafeHtml.Sanitize("<p style='user-select:text'>secret</p>",12,false);Check(html.Contains("user-select:none!important")&&!html.Contains("user-select:text"));});
        Test("format family size indent table image safe attributes",()=>{var s=SafeHtml.Fragment("<h2>見出し</h2><p style='font-family:Meiryo;font-size:24pt;margin-left:40px;color:#008000'>本文</p><table><tr><td colspan='2'>結合</td></tr></table>");Check(s.Contains("font-family:Meiryo")&&s.Contains("24pt")&&s.Contains("40px")&&s.Contains("colspan=\"2\""));});
        Test("Viewer title no search and splitter",()=>{using var c=Unlock(capsule);using var f=new CipherCapsule.Viewer.ViewerForm(c);Check(f.Text=="CipherCapsule — メッセージ閲覧");Check(AllControls(f).OfType<SplitContainer>().Single().Orientation==Orientation.Horizontal);Check(!AllControls(f).Any(x=>x.Text=="次を検索"));});
        Test("eye initial label and two different actual bitmaps",()=>{using var p=new PasswordPanel();Check(p.Eye.Text=="表示"&&p.Eye.Image!=null);using var ms=new MemoryStream();p.Eye.Image!.Save(ms,System.Drawing.Imaging.ImageFormat.Png);var old=ms.ToArray();p.Toggle();using var ms2=new MemoryStream();p.Eye.Image!.Save(ms2,System.Drawing.Imaging.ImageFormat.Png);Check(p.Eye.Text=="隠す"&&!old.SequenceEqual(ms2.ToArray()));});
        Test("INI defaults roundtrip malformed fallback no secrets",()=>{var p=Path.Combine(AppContext.BaseDirectory,"CipherCapsule.ini");File.Delete(p);var s=BuilderApp::CipherCapsule.Builder.Settings.Load();Check(s.Font==12);s.Font=17;s.Kind=1;s.Save();Check(BuilderApp::CipherCapsule.Builder.Settings.Load().Font==17);string txt=File.ReadAllText(p);var lines=File.ReadAllLines(p);var reveal=lines.Where(x=>x.StartsWith("PasswordRevealed=")).ToArray();string rest=string.Join("\n",lines.Where(x=>!x.StartsWith("PasswordRevealed=")));Check(reveal.Length==1&&reveal[0] is "PasswordRevealed=0" or "PasswordRevealed=1"&&!txt.Contains(Password)&&!rest.Contains("Password")&&!txt.Contains("Body"));File.WriteAllText(p,"bad format");Check(BuilderApp::CipherCapsule.Builder.Settings.Load().Font==12);File.Delete(p);});
        Test("Builder initial SHA512 ON and no persisted password",()=>{using var b=new BuilderType();var pw=(BuilderPassword)typeof(BuilderType).GetField("password",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(b)!;Check(pw.Primary.Text==""&&pw.Confirm.Text=="");Check(AllControls(b).OfType<CheckBox>().Single(x=>x.Text.StartsWith("SHA-512")).Checked);});
    }
    static void RunEditor()
    {
        using var form=new AppForm{Text="CipherCapsule editor behavioral test",Size=new Size(1200,900)};using var ed=new EditorType();form.Controls.Add(ed);
        ed.EditorBrowser.CoreWebView2InitializationCompleted+=(_,e)=>{if(e.IsSuccess){ed.EditorBrowser.CoreWebView2.FrameNavigationStarting+=(_,x)=>Console.WriteLine("Editor frame navigation: "+x.Uri+" cancelled="+x.Cancel);ed.EditorBrowser.CoreWebView2.WebResourceResponseReceived+=(_,x)=>{if(x.Response.StatusCode>=400)Console.WriteLine("Editor resource blocked: "+x.Request.Uri);};}};
        form.Shown+=async(_,_)=>{
            try{
                for(int i=0;i<250&&!ed.IsReady;i++)await Task.Delay(100);Test("TinyMCE offline initialization GPL Japanese",()=>Check(ed.IsReady));if(!ed.IsReady){if(ed.EditorBrowser.CoreWebView2!=null)Console.WriteLine(await ed.EditorBrowser.CoreWebView2.ExecuteScriptAsync("JSON.stringify({url:location.href,body:document.body.innerText,tiny:typeof tinymce,ready:window.ccReady,error:window.ccError,csp:window.ccCsp,initialized:tinymce.activeEditor?.initialized,frames:[...document.querySelectorAll('iframe')].map(f=>({src:f.src,body:f.contentDocument?.body?.innerHTML}))})"));return;}
                var c=ed.EditorBrowser.CoreWebView2;string version=await c.ExecuteScriptAsync("tinymce.majorVersion");Test("TinyMCE 8 actual running",()=>Check(version=="\"8\""));
                await ed.SetContent("<p>日本語 Unicode 🔑 e\u0301</p><p><a href='https://example.com/'>リンク</a></p><table><tbody><tr><td>セル</td></tr></tbody></table>");
                await ed.Switch(1);await ed.Switch(0);string value=await ed.GetContent();Test("visual/code roundtrip Unicode links table",()=>Check(value.Contains("日本語")&&value.Contains("href=")&&value.Contains("<td>セル</td>")));
                await c.ExecuteScriptAsync("(()=>{const e=tinymce.activeEditor;e.setContent('<p>装飾テスト</p>');e.selection.select(e.getBody().firstChild);e.execCommand('Bold');e.execCommand('Italic');})()");value=await ed.GetContent();Test("bold italic commands change actual HTML",()=>Check(value.Contains("strong")&&value.Contains("em")));
                await c.ExecuteScriptAsync("(()=>{const e=tinymce.activeEditor;e.setContent('<p>undo対象</p>');e.undoManager.add();e.insertContent('追加');})()");string added=await ed.GetContent();await c.ExecuteScriptAsync("tinymce.activeEditor.undoManager.undo()");string undone=await ed.GetContent();await c.ExecuteScriptAsync("tinymce.activeEditor.undoManager.redo()");string redone=await ed.GetContent();Test("editor undo and redo actual changes",()=>Check(added!=undone&&redone==added));
                await c.ExecuteScriptAsync("(()=>{const e=tinymce.activeEditor;e.setContent('<p>Intellect Archives</p>');e.focus();e.selection.select(e.getBody().firstChild,true);const dt=new DataTransfer();dt.setData('text/plain','https://search.0523.jp');e.getBody().dispatchEvent(new ClipboardEvent('paste',{clipboardData:dt,bubbles:true,cancelable:true}));})()");value=await ed.GetContent();Test("selected text URL paste becomes safe link",()=>Check(value.Contains("https://search.0523.jp")&&value.Contains("Intellect Archives")));
                await c.ExecuteScriptAsync("tinymce.activeEditor.execCommand('unlink')");value=await ed.GetContent();Test("unlink removes href",()=>Check(!value.Contains("href=")));
                await c.ExecuteScriptAsync("(()=>{const e=tinymce.activeEditor;e.setContent('<p>書式</p>');e.selection.select(e.getBody().firstChild,true);e.execCommand('FontName',false,'Meiryo');e.execCommand('FontSize',false,'24pt');e.execCommand('ForeColor',false,'#008000');e.execCommand('HiliteColor',false,'#ffff00');e.execCommand('Underline');e.execCommand('Strikethrough');})()");value=await ed.GetContent();Console.WriteLine("Format HTML: "+value);Test("font family size colors underline strike actual HTML",()=>Check(value.Contains("Meiryo",StringComparison.OrdinalIgnoreCase)&&value.Contains("24pt")&&(value.Contains("008000")||value.Contains("0, 128, 0"))&&(value.Contains("ffff00",StringComparison.OrdinalIgnoreCase)||value.Contains("255, 255, 0"))&&(value.Contains("underline")||value.Contains("<u>"))&&(value.Contains("line-through")||value.Contains("<s>"))));
                await c.ExecuteScriptAsync("(()=>{const e=tinymce.activeEditor;e.setContent('<p>見出し</p>');e.selection.select(e.getBody().firstChild,true);e.execCommand('FormatBlock',false,'h3');e.execCommand('JustifyCenter');})()");value=await ed.GetContent();Test("heading and alignment actual HTML",()=>Check(value.Contains("<h3")&&value.Contains("center")));
                await c.ExecuteScriptAsync("(()=>{const e=tinymce.activeEditor;e.setContent('<p>リスト</p>');e.selection.select(e.getBody().firstChild,true);e.execCommand('InsertUnorderedList');})()");value=await ed.GetContent();Test("bullet list actual HTML",()=>Check(value.Contains("<ul>")&&value.Contains("<li>")));
                await c.ExecuteScriptAsync("(()=>{const e=tinymce.activeEditor;e.setContent('<p>表</p>');e.execCommand('mceInsertTable',false,{rows:2,columns:2});})()");value=await ed.GetContent();Test("table command creates cells",()=>Check(value.Split("<td").Length>=5));
                await c.ExecuteScriptAsync("(()=>{const e=tinymce.activeEditor;e.selection.setCursorLocation(e.getBody().querySelector('td'),0);e.execCommand('mceTableInsertRowAfter');e.execCommand('mceTableInsertColAfter');})()");value=await ed.GetContent();Test("table row and column insertion",()=>Check(value.Split("<td").Length>=10));
                using(var image=new Bitmap(3,3)){using var stream=new MemoryStream();image.Save(stream,System.Drawing.Imaging.ImageFormat.Png);string data="data:image/png;base64,"+Convert.ToBase64String(stream.ToArray());await c.ExecuteScriptAsync("tinymce.activeEditor.insertContent("+JsonSerializer.Serialize("<p><img src='"+data+"' alt='日本語代替テキスト' width='3' height='3'></p>")+")");value=await ed.GetContent();Test("embedded image insertion attributes and tab synchronization",()=>Check(value.Contains("data:image/png;base64,")&&value.Contains("日本語代替テキスト")));await ed.Switch(1);await ed.Switch(0);value=await ed.GetContent();Test("image persists through visual/code roundtrip",()=>Check(value.Contains("data:image/png;base64,")));}
                string plugins=await c.ExecuteScriptAsync("JSON.stringify(Object.keys(tinymce.activeEditor.plugins))");Test("required free plugins loaded",()=>Check(new[]{"table","image","link","charmap","searchreplace","code","help"}.All(plugins.Contains)));
                await ed.Switch(1);Test("code tab actual selection",()=>Check(ed.IsCode));await ed.Switch(0);
                string blocked=await c.ExecuteScriptAsync("JSON.stringify(tinymce.activeEditor.schema.getValidElements().script || null)");Test("editor schema rejects script elements",()=>Check(blocked=="\"null\""||blocked=="null"));
                bool cleanup=await ed.CloseAsync();Test("editor browser exits and profile removed",()=>Check(cleanup));
            }catch(Exception ex){Test("editor runtime",()=>throw ex);}finally{form.Close();}
        };Application.Run(form);
    }
}
